function modeText(modeKey, field) {
  const mode = addressingModeText[modeKey];
  const language = mode?.[currentLanguage] || mode?.en || mode?.hu;
  return language?.[field] || modeKey;
}

const mnemonicDescriptionsHu = (() => {
  const map = {};
  for (const items of Object.values(mnemonicLibrary)) {
    for (const item of items) {
      if (item.mnemonic && item.description) map[item.mnemonic] = item.description;
    }
  }
  return map;
})();

function getItemDescription(item) {
  if (currentLanguage === "hu") return item.description;
  return translations[currentLanguage]?.mnemonicDescriptions?.[item.mnemonic] || translations.en.mnemonicDescriptions[item.mnemonic] || item.description;
}

const mnemonicSyntax = (name, ...parts) => `.${name.toLowerCase()} ${parts.join(", ")}`;

