function _canUseUltimateBasicMode(tab = _getActiveTab()) {
  // Az import és a beépített minta útvonal nélkül is assembler-forrás marad.
  const file = tab?.filePath || (/\.(asm|s|a|a65|inc|acme|json|c64va|proj)$/i.test(tab?.name || "") ? tab.name : "");
  return !file || /\.ub$/i.test(file);
}

function _isBoundUbTab(tab = _getActiveTab()) {
  return /\.ub$/i.test(tab?.filePath || "");
}

function setUltimateBasicMode(on, { restoreAssemblerMode = true } = {}) {
  if (!on && ultimateBasicMode && _isBoundUbTab()) {
    showViceToast?.(t("asmUbFileBlocked"), true);
    return;
  }
  if (on && !_canUseUltimateBasicMode()) {
    showViceToast?.(t("ubAsmFileBlocked"), true);
    _updateEditorModeIndicator();
    return;
  }
  const previousAssemblerEditorMode = expertMode ? "expert" : "block";
  const leavingUb = !on && ultimateBasicMode;
  if (!on && ultimateBasicMode) {
    const current = _getActiveTab();
    if (current?.id === _ubEditorTabId && current.editorMode === "ub" && ubEditor) {
      current.ubText = ubEditor.value;
      current.ubFilePath = _ubFilePath;
      current.ubBreakpointLines = [..._ubBreakpointLines];
    }
  }
  if (on && expertMode) setExpertMode(false, { switchingToUb: true });
  if (on) {
    lastAssemblerEditorMode = previousAssemblerEditorMode;
    localStorage.setItem("lastAssemblerEditorMode", lastAssemblerEditorMode);
  }
  ultimateBasicMode = !!on;
  document.body.classList.toggle("ub-mode", ultimateBasicMode);
  if (ubPanel) ubPanel.hidden = !ultimateBasicMode;
  ubModeTbBtn?.classList.toggle("main-tb-btn--active", ultimateBasicMode);
  ubModeTbBtn?.setAttribute("aria-pressed", String(ultimateBasicMode));
  _updateWorkingFolderButtonTooltip();
  _updateEditorModeIndicator();
  _acmeBuildButtonSync();
  if (ultimateBasicMode) {
    const current = _getActiveTab();
    if (current && _ubEditorTabId !== current.id) {
      ubEditor.value = current.ubText || "";
      _ubFilePath = current.ubFilePath || current.filePath || "";
      _ubBreakpointLines = [...(current.ubBreakpointLines || [])];
      _ubDirty = !!current.dirty;
      _ubEditorTabId = current.id;
    }
    if (current) current.editorMode = "ub";
    ubEditor.focus();
    _ubUpdateCursor();
    ubPanel.classList.toggle("ub-show-lines", _ubLinesEnabled);
    ubPanel.classList.toggle("ub-show-minimap", _ubMinimapEnabled);
    ubPanel.classList.toggle("ub-hide-output", !_ubOutputVisible);
    _ubSetToggle("ub-output-btn", _ubOutputVisible);
    _ubSetToggle("ub-autocomplete-btn", _ubAutocompleteEnabled);
    _ubSetToggle("ub-explicit-btn", _ubExplicit);
    _ubApplyLeftViews(false);
    _ubRefreshEditor();
    _ubRenderProjectFiles();
    _ubRenderCommandReference();
  }
  _toolkitPlace();
  // back to the assembler editor the user left: ACME and block-locked projects have text only
  if (leavingUb && restoreAssemblerMode && !expertMode
      && (lastAssemblerEditorMode === "expert" || assemblerSyntax === "acme" || _blockModeBlocked())) {
    setExpertMode(true);
    return;
  }
  if (!ultimateBasicMode && !expertMode && _programCardsStale) renderProgram();
  renderMemoryMap();
  _historySyncCurrent();
  saveUiSettings();
}

function _updateWorkingFolderButtonTooltip() {
  const text = t(_isUltimateBasicEditorActive() ? "setUbWorkingFolderHint" : "setVaWorkingFolderHint");
  setWorkingFolderButton?.setAttribute("aria-label", text);
}

function _isUltimateBasicEditorActive() {
  return ultimateBasicMode
    || document.body.classList.contains("ub-mode")
    || _getActiveTab()?.editorMode === "ub"
    || (ubPanel && !ubPanel.hidden);
}

function _ubApplyLeftViews(persist = true) {
  const projectView = document.getElementById("ub-project-view");
  const commandsView = document.getElementById("ub-commands-view");
  const commandsPanel = document.getElementById("ub-commands-panel");
  if (projectView) { projectView.hidden = !_ubProjectVisible; projectView.classList.toggle("ub-left-view--active", _ubProjectVisible); }
  if (commandsPanel) commandsPanel.hidden = !_ubCommandsVisible;
  if (commandsView) commandsView.classList.toggle("ub-left-view--active", _ubCommandsVisible);
  ubPanel?.classList.toggle("ub-show-project", _ubProjectVisible);
  ubPanel?.classList.toggle("ub-show-commands", _ubCommandsVisible);
  _ubSetToggle("ub-project-btn", _ubProjectVisible);
  _ubSetToggle("ub-help-btn", _ubCommandsVisible);
  if (_ubCommandsVisible) _ubRenderCommandReference();
  if (persist) saveUiSettings();
}

const _UB_KEYWORDS = new Set(("var const print print# input if then else end for to step next while repeat until loop break continue times sub fn call return goto gosub label graphics on off multi block display gcls cls fast plot plot4 mplot line circle circle4 rect fill paint flip sprite sprite_frame sprdef chardef charset expand priority sound sfx org tune music play stop pause resume sid volume irq irq_exit nmi nmi_exit cia_timer onerr data read asm include incbin load open close save chain memcopy drawmem map koala show hide set draw poke poke16 sys bye exit wait delay raster getch joy reu stash fetch speed badlines color border bg text screen cursor at lowercase uppercase select case and or xor not bnot mod shl shr inc dec erase scroll type endtype pen mline mrect mcircle dim function do wend elseif option").split(" "));
const _UB_TYPES = new Set(["int", "word", "float", "string", "array", "array_word"]);
// BASIC type names used after `as` (dim / function / sub). The compiler treats them and
// `as` as context words, not reserved ones, so they are only coloured in a type position.
const _UB_BASIC_TYPES = new Set(["byte", "integer", "single", "double"]);
// Words the compiler reads as keywords only right after the given keyword (case is, map view,
// wait key, scroll row|x|y) or anywhere in a scroll statement.
const _UB_CONTEXT_KEYWORDS = new Map([["case", new Set(["is"])], ["map", new Set(["view"])], ["wait", new Set(["key"])], ["scroll", new Set(["row", "x", "y"])], ["print", new Set(["using"])], ["option", new Set(["basic"])]]);
const _UB_SCROLL_WORDS = new Set(["left", "right", "narrow", "wide"]);
const _UB_FUNCTIONS = new Set(("str_to_int numstr chr$ str$ inkey waitkey len asc val reudet reu_present turbo clamp peek peek16 rnd abs min max sgn spc tab joy mouse_x mouse_x_hi mouse_y mouse_btn sprhit sprbghit sprite_hit sprite_bg_hit sprite_x sprite_y map_tile map_color box_hit sin cos hex bin getch left$ right$ mid$").split(" "));
const _UB_ASM_MNEMONICS = new Set(("adc and asl bcc bcs beq bit bmi bne bpl brk bvc bvs clc cld cli clv cmp cpx cpy dec dex dey eor inc inx iny jmp jsr lda ldx ldy lsr nop ora pha php pla plp rol ror rti rts sbc sec sed sei sta stx sty tax tay tsx txa txs tya").split(" "));

function _ubEsc(value) { return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); }

let _ubAcActive = -1;
function _ubAcEl() {
  let el = document.getElementById("ub-ac");
  if (!el) { el = document.createElement("div"); el.id = "ub-ac"; el.className = "expert-autocomplete"; el.hidden = true; document.body.appendChild(el); }
  return el;
}
function _ubAcVisible() { const el = document.getElementById("ub-ac"); return !!el && !el.hidden; }
function _ubAcHide() { const el = document.getElementById("ub-ac"); if (el) el.hidden = true; _ubAcActive = -1; }
function _ubAcMove(direction) {
  const items = _ubAcEl().querySelectorAll(".expert-ac-item"); if (!items.length) return;
  items[_ubAcActive]?.classList.remove("active");
  _ubAcActive = _ubAcActive < 0
    ? (direction > 0 ? 0 : items.length - 1)
    : (_ubAcActive + direction + items.length) % items.length;
  items[_ubAcActive].classList.add("active"); items[_ubAcActive].scrollIntoView({ block: "nearest" });
}
function _ubAcCommit() {
  const el = _ubAcEl(); const item = el.querySelector(".expert-ac-item.active") || el.querySelector(".expert-ac-item");
  if (!item || !ubEditor) return false;
  const pos = ubEditor.selectionStart; const before = ubEditor.value.slice(0, pos); const match = before.match(/[A-Za-z_][A-Za-z0-9_]*\$?$/);
  if (!match) return false;
  ubEditor.setRangeText(item.dataset.value, pos - match[0].length, pos, "end");
  _ubAcHide(); ubEditor.dispatchEvent(new Event("input", { bubbles: true })); return true;
}
function _ubAcUpdate() {
  if (!_ubAutocompleteEnabled || !ubEditor || document.activeElement !== ubEditor) { _ubAcHide(); return; }
  const pos = ubEditor.selectionStart; const before = ubEditor.value.slice(0, pos); const match = before.match(/[A-Za-z_][A-Za-z0-9_]*\$?$/);
  if (!match || match[0].length < 2) { _ubAcHide(); return; }
  const typed = match[0].toLowerCase();
  // Several entries share a first word ("exit" / "exit sub"): the exact name wins.
  const descriptions = new Map();
  _UB_COMMAND_REFERENCE.forEach(([name,, desc]) => {
    const key = name.split(" ")[0].toLowerCase();
    if (!descriptions.has(key) || name === key) descriptions.set(key, _ubGetCommandDescription(name) || desc);
  });
  const words = [...new Set([..._UB_KEYWORDS, ..._UB_TYPES, ..._UB_BASIC_TYPES, ..._UB_FUNCTIONS])].filter(word => word.startsWith(typed) && word !== typed).sort().slice(0, 12);
  if (!words.length) { _ubAcHide(); return; }
  const el = _ubAcEl(); _ubAcActive = -1;
  el.innerHTML = words.map(word => `<div class="expert-ac-item" data-value="${_ubEsc(word)}"><span class="expert-ac-item-kw">${_ubEsc(word)}</span><span class="expert-ac-item-desc">${_ubEsc(descriptions.get(word) || (_UB_FUNCTIONS.has(word) ? "function" : (_UB_TYPES.has(word) || _UB_BASIC_TYPES.has(word)) ? "type" : "keyword"))}</span></div>`).join("");
  el.querySelectorAll(".expert-ac-item").forEach(item => item.addEventListener("mousedown", event => { event.preventDefault(); _ubAcActive = [...item.parentNode.children].indexOf(item); _ubAcCommit(); }));
  const rect = ubEditor.getBoundingClientRect();
  const editorStyle = getComputedStyle(ubEditor);
  const lineHeight = parseFloat(editorStyle.lineHeight) || 21;
  const paddingTop = parseFloat(editorStyle.paddingTop) || 0;
  const line = before.split("\n").length - 1;
  const lineTop = rect.top + paddingTop + line * lineHeight - ubEditor.scrollTop;
  const lineBottom = lineTop + lineHeight;
  const topBoundary = Math.max(8, rect.top + 8);
  const bottomBoundary = Math.min(window.innerHeight - 8, rect.bottom - 8);
  const belowSpace = Math.max(32, bottomBoundary - lineBottom - 4);
  const aboveSpace = Math.max(32, lineTop - topBoundary - 4);
  el.style.left = `${Math.min(rect.right - 300, rect.left + 60)}px`;
  el.style.maxHeight = "260px";
  el.hidden = false;
  const naturalHeight = el.offsetHeight;
  const openBelow = belowSpace >= Math.min(naturalHeight, 120) || belowSpace >= aboveSpace;
  const availableHeight = openBelow ? belowSpace : aboveSpace;
  el.style.maxHeight = `${Math.min(260, availableHeight)}px`;
  const popupHeight = el.offsetHeight;
  el.style.top = `${openBelow ? lineBottom + 4 : lineTop - popupHeight - 4}px`;
}

function _ubFormatText(source) {
  // Open blocks, innermost last. The kind matters for LOOP: directly inside a DO it closes
  // the block (loop / loop while c / loop until c), anywhere else it opens loop ... end.
  const stack = [];
  let inAsm = false;
  const codePart = raw => {
    let quote = false;
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === '"') quote = !quote;
      if (!quote && !inAsm && (raw[i] === "'" || (raw[i] === "#" && !/\bprint$/i.test(raw.slice(0, i))))) return raw.slice(0, i);
      if (!quote && inAsm && raw[i] === ";") return raw.slice(0, i);
    }
    return raw;
  };
  const lastStatement = code => {
    let quote = false;
    let start = -1;
    for (let i = 0; i < code.length; i++) {
      if (code[i] === '"') quote = !quote;
      else if (!quote && code[i] === ":") start = i;
    }
    return start < 0 ? "" : code.slice(start + 1).trim();
  };
  // do while c : ... : loop and friends close on their own line and must not indent.
  const oneLineEnd = { do: /^loop\b/, while: /^(?:wend|end)\b/, for: /^next\b/, repeat: /^until\b/, loop: /^end\b/, times: /^end\b/ };
  return String(source || "").split("\n").map(raw => {
    const content = raw.trim();
    if (!content) return "";
    const code = codePart(content).trim().toLowerCase();
    const closesDo = stack[stack.length - 1] === "do" && /^loop\s*(?:$|[:;]|while\b|until\b)/.test(code);
    if (closesDo || /^(?:end\b|endtype\b|wend\b|next\b|until\b|else\b|elseif\b|case\b|\})/.test(code)) stack.pop();
    const formatted = `${"  ".repeat(stack.length)}${content.replace(/\s+$/, "")}`;
    const opener = closesDo ? "" : (code.match(/^(sub|fn|function|for|while|do|loop|times|repeat|select|sprdef|chardef|type|tune)\b/) || [])[1] || "";
    const opens = (opener && !oneLineEnd[opener]?.test(lastStatement(code)))
      || /^if\b.*\bthen\s*$/.test(code)
      || /^asm\s*\{\s*$/.test(code)
      || /^(?:else\b|elseif\b|case\b)/.test(code);
    if (opens) stack.push(opener || "block");
    if (/^asm\s*\{\s*$/.test(code)) inAsm = true;
    if (/^\}/.test(code)) inAsm = false;
    return formatted;
  }).join("\n");
}

function _ubFormatSource() {
  if (!ubEditor) return;
  const before = ubEditor.value;
  const formatted = _ubFormatText(before);
  if (formatted === before) return;
  const mapPosition = (position) => {
    const safePosition = Math.max(0, Math.min(position ?? 0, before.length));
    const beforeLines = before.split("\n");
    const formattedLines = formatted.split("\n");
    const prefix = before.slice(0, safePosition);
    const line = prefix.split("\n").length - 1;
    const lineStart = before.lastIndexOf("\n", safePosition - 1) + 1;
    const column = safePosition - lineStart;
    const beforeIndent = (beforeLines[line] || "").match(/^\s*/)[0].length;
    const formattedLine = formattedLines[Math.min(line, formattedLines.length - 1)] || "";
    const formattedIndent = formattedLine.match(/^\s*/)[0].length;
    const mappedColumn = column <= beforeIndent
      ? Math.min(column, formattedIndent)
      : formattedIndent + Math.min(column - beforeIndent, Math.max(0, formattedLine.length - formattedIndent));
    const formattedLineStart = formattedLines.slice(0, line).join("\n").length + (line > 0 ? 1 : 0);
    return formattedLineStart + mappedColumn;
  };
  const selectionStart = mapPosition(ubEditor.selectionStart);
  const selectionEnd = mapPosition(ubEditor.selectionEnd);
  ubEditor.value = formatted;
  ubEditor.setSelectionRange(selectionStart, selectionEnd);
  ubEditor.dispatchEvent(new Event("input", { bubbles: true }));
  _ubSetStatus(t("ubFormatSource"));
}

function _ubHighlightSource(source) {
  let inAsm = false;
  let inTune = false;
  return String(source || "").split("\n").map((raw, lineIndex) => {
    const trimmed = raw.trim().toLowerCase();
    if (/^asm\s*\{/.test(trimmed)) inAsm = true;
    if (!inAsm && /^tune\b/.test(trimmed)) inTune = true;
    const tuneWord = inTune && /^\s*(inst|imod|ifilt|igate|itab|order|pat|speed)\b/i.test(raw) ? raw.match(/^\s*(\w+)/)[1].toLowerCase() : "";
    let code = raw;
    let comment = "";
    if (!inAsm) {
      let quote = false;
      for (let i = 0; i < raw.length; i++) {
        if (raw[i] === '"') quote = !quote;
        if (!quote && (raw[i] === "#" || raw[i] === "'")) {
          // PRINT# is one UB token; every other # (and the QBasic ') outside a string starts a comment.
          if (raw[i] === "#" && /\bprint$/i.test(raw.slice(0, i))) continue;
          code = raw.slice(0, i); comment = raw.slice(i); break;
        }
      }
      if (/^\s*rem\b/i.test(code)) { comment = code; code = ""; }
    } else {
      const idx = raw.indexOf(";");
      if (idx >= 0) { code = raw.slice(0, idx); comment = raw.slice(idx); }
    }
    let html = "";
    const re = /("(?:[^"\\]|\\.)*")|(\$[0-9a-f]+|%[01]+|\b\d+(?:\.\d+)?\b)|(print#|[A-Za-z_][A-Za-z0-9_]*\$?)/gi;
    let last = 0;
    let prevWord = "";
    let scrollStatement = false;
    for (const match of code.matchAll(re)) {
      const gap = code.slice(last, match.index);
      html += _ubEsc(gap);
      const token = match[0];
      const lower = token.toLowerCase();
      // `as <type>` and the context keywords are plain identifiers anywhere else.
      if (gap.includes(":")) scrollStatement = false;
      const adjacent = !inAsm && !gap.trim();
      const afterAs = adjacent && prevWord === "as";
      const asKeyword = !inAsm && ((lower === "as" && /^\s+(?:byte|int|integer|word|single|double|float|string)\b/i.test(code.slice(match.index + token.length)))
        || (adjacent && _UB_CONTEXT_KEYWORDS.get(prevWord)?.has(lower))
        || (scrollStatement && _UB_SCROLL_WORDS.has(lower)));
      const cls = match[1] ? "ub-string" : match[2] ? "ub-number" : _UB_TYPES.has(lower) || (afterAs && _UB_BASIC_TYPES.has(lower)) ? "ub-type" : _UB_FUNCTIONS.has(lower) ? "ub-fn" : asKeyword || _UB_KEYWORDS.has(lower) || (inAsm && _UB_ASM_MNEMONICS.has(lower)) || (tuneWord && lower === tuneWord && match.index === code.search(/\S/)) ? "ub-kw" : "";
      html += cls ? `<span class="${cls}">${_ubEsc(token)}</span>` : _ubEsc(token);
      last = match.index + token.length;
      prevWord = match[3] ? lower : "";
      if (!inAsm && lower === "scroll") scrollStatement = true;
    }
    html += _ubEsc(code.slice(last));
    if (comment) html += `<span class="ub-comment">${_ubEsc(comment)}</span>`;
    if (inAsm && /^\s*\}/.test(raw)) inAsm = false;
    if (inTune && /^\s*end\b/i.test(raw)) inTune = false;
    return html;
  }).join("\n") + "\n";
}

function _ubRefreshEditor() {
  const code = document.getElementById("ub-highlight-code");
  if (code) code.innerHTML = _ubHighlightEnabled ? _ubHighlightSource(ubEditor.value) : _ubEsc(ubEditor.value) + "\n";
  const lineCount = ubEditor.value.split("\n").length;
  const lineDigits = Math.max(2, String(lineCount).length);
  const gutterWidth = Math.max(48, Math.ceil(lineDigits * _ubFontSize * 0.62 + 28)) + (_ubHeatEnabled ? Math.ceil(_ubFontSize * 0.62 * 4 + 14) : 0);
  const costs = _ubHeatEnabled ? (_ubLineCostMap || (_ubLineCostMap = _ubLineCost(_ubLastResult))) : null;
  let maxCost = 1;
  costs?.forEach((c) => { if (c.bytes > maxCost) maxCost = c.bytes; });
  ubPanel?.style.setProperty("--ub-line-number-width", `${gutterWidth}px`);
  const gutter = document.getElementById("ub-line-numbers-content");
  if (gutter) {
    gutter.innerHTML = "";
    const bookmarks = new Set(_bmLines("ub"));
    ubEditor.value.split("\n").forEach((_, line) => {
      const marker = document.createElement("button");
      marker.type = "button";
      marker.className = "source-line-number bp-toggle" + (_getTabBreakpointLines("ub").includes(line) ? " bp-active" : "") + (bookmarks.has(line) ? " bm-active" : "");
      marker.textContent = String(line + 1);
      marker.setAttribute("aria-label", `${t("breakpointToggle")} ${line + 1}`);
      marker.addEventListener("click", (e) => (e.ctrlKey || e.metaKey) ? _bmToggle("ub", line) : _setBreakpointLine("ub", line));
      const cost = costs?.get(line);
      if (cost) {
        marker.dataset.cost = String(cost.bytes);
        const heat = Math.sqrt(cost.bytes / maxCost);
        marker.style.background = `linear-gradient(90deg, rgba(249, 115, 22, ${(0.1 + heat * 0.45).toFixed(2)}) ${Math.round(heat * 100)}%, transparent ${Math.round(heat * 100)}%)`;
      }
      gutter.appendChild(marker);
    });
  }
  _ubUpdateCursor();
  _ubSyncScroll();
  _ubDrawMinimap();
  _ubRenderProjectSymbols();
  _ubScheduleLint();
}

function _ubGotoLine(lineIndex) {
  if (!ubEditor || lineIndex < 0) return;
  const lines = ubEditor.value.split("\n");
  const start = lines.slice(0, lineIndex).join("\n").length + (lineIndex > 0 ? 1 : 0);
  const end = start + (lines[lineIndex]?.length || 0);
  ubEditor.focus();
  ubEditor.setSelectionRange(start, end);
  const lineHeight = parseFloat(getComputedStyle(ubEditor).lineHeight) || 21;
  const paddingTop = parseFloat(getComputedStyle(ubEditor).paddingTop) || 16;
  ubEditor.scrollTop = Math.max(0, paddingTop + lineIndex * lineHeight - ubEditor.clientHeight / 3);
}

// ── Könyvjelzők és ugrás sorra (Expert + UB) ──
// Forrássor-indexek fülenként (tab.expertBookmarks / tab.ubBookmarks), fájlútvonal
// szerint localStorage-ban is ("c64va-bookmarks"), hogy újraindítás után megmaradjanak.
// Csak függvények: az init a szkript kiértékelése közben is renderelhet guttert (TDZ).
function _bmPath(kind) {
  const tab = _getActiveTab();
  return kind === "ub" ? (_ubFilePath || tab?.ubFilePath || tab?.filePath || "") : (tab?.filePath || "");
}

function _bmStored() {
  try { return JSON.parse(localStorage.getItem("c64va-bookmarks") || "{}") || {}; } catch (_) { return {}; }
}

function _bmLines(kind) {
  const tab = _getActiveTab();
  if (!tab) return [];
  const key = kind + "Bookmarks";
  const path = _bmPath(kind);
  if (!Array.isArray(tab[key]) || tab[key + "Path"] !== path) {
    const saved = path ? _bmStored()[path] : null;
    // an untitled tab that just got its first path keeps its bookmarks
    const keep = Array.isArray(tab[key]) && !tab[key + "Path"] && !Array.isArray(saved);
    tab[key] = keep ? tab[key] : Array.isArray(saved) ? saved.filter(Number.isInteger) : [];
    tab[key + "Path"] = path;
    tab[kind + "BookmarkSnap"] = undefined;
    if (keep && path) _bmSet(kind, tab[key], false);
  }
  return tab[key];
}

function _bmSet(kind, lines, refresh = true) {
  const sorted = [...new Set(lines)].filter(n => Number.isInteger(n) && n >= 0).sort((a, b) => a - b);
  const tab = _getActiveTab();
  if (!tab) return;
  tab[kind + "Bookmarks"] = sorted;
  const path = _bmPath(kind);
  if (path) {
    const store = _bmStored();
    if (sorted.length) store[path] = sorted; else delete store[path];
    try { localStorage.setItem("c64va-bookmarks", JSON.stringify(store)); } catch (_) {}
  }
  if (refresh) {
    if (kind === "ub") _ubRefreshEditor(); else _expertUpdateLineNumbers();
  }
}

function _bmText(kind) {
  return kind === "ub" ? (ubEditor?.value || "") : _expertGetSourceText();
}

function _bmCaretLine(kind) {
  if (kind === "ub") return ubEditor.value.slice(0, ubEditor.selectionStart).split("\n").length - 1;
  const sourcePos = _expertDisplayPosToSourcePos(expertEditor.selectionStart ?? 0);
  return _expertGetSourceText().slice(0, sourcePos).split("\n").length - 1;
}

function _bmGoto(kind, line) {
  if (kind === "ub") _ubGotoLine(line); else _expertGotoSourceLine(line);
}

function _bmToggle(kind, line = _bmCaretLine(kind)) {
  const lines = _bmLines(kind);
  _bmSet(kind, lines.includes(line) ? lines.filter(l => l !== line) : [...lines, line]);
}

function _bmJump(kind, dir) {
  const lines = _bmLines(kind);
  if (!lines.length) return;
  const cur = _bmCaretLine(kind);
  const target = dir > 0
    ? (lines.find(l => l > cur) ?? lines[0])
    : ([...lines].reverse().find(l => l < cur) ?? lines[lines.length - 1]);
  _bmGoto(kind, target);
}

/* Moves the bookmarks with the edited text: lines above the changed block stay,
   lines below it shift by the line delta, lines inside it are clamped into it. */
function _bmTrackEdit(kind) {
  const tab = _getActiveTab();
  if (!tab) return;
  const lines = _bmLines(kind);
  const snapKey = kind + "BookmarkSnap";
  const text = _bmText(kind);
  const prev = tab[snapKey];
  tab[snapKey] = text;
  if (typeof prev !== "string" || prev === text || !lines.length) return;
  const a = prev.split("\n"), b = text.split("\n");
  let p = 0;
  while (p < a.length && p < b.length && a[p] === b[p]) p++;
  let s = 0;
  while (s < a.length - p && s < b.length - p && a[a.length - 1 - s] === b[b.length - 1 - s]) s++;
  const oldEnd = a.length - s, newEnd = b.length - s, delta = b.length - a.length;
  const moved = lines.map(l => l < p ? l : l >= oldEnd ? l + delta : Math.min(l, Math.max(p, newEnd - 1)));
  if (moved.some((l, i) => l !== lines[i])) _bmSet(kind, moved, false);
}

function _bmHandleKey(kind, e) {
  if (e.key === "F2" && !e.altKey) {
    e.preventDefault();
    if (e.ctrlKey || e.metaKey) _bmToggle(kind); else _bmJump(kind, e.shiftKey ? -1 : 1);
    return true;
  }
  if ((e.ctrlKey || e.metaKey) && !e.shiftKey && !e.altKey && e.key.toLowerCase() === "g") {
    e.preventDefault();
    _gotoLineOpen(kind);
    return true;
  }
  return false;
}

function _gotoLineOpen(kind) {
  const dialog = document.getElementById("goto-line-dialog");
  const input = document.getElementById("goto-line-input");
  if (!dialog || !input) return;
  dialog.dataset.kind = kind;
  const max = _bmText(kind).split("\n").length;
  document.getElementById("goto-line-title").textContent = t("gotoLine");
  document.getElementById("goto-line-hint").textContent = tf("gotoLineHint", { max });
  input.value = String(_bmCaretLine(kind) + 1);
  input.classList.remove("goto-line-input--error");
  dialog.showModal();
  input.select();
}

function _gotoLineSubmit() {
  const dialog = document.getElementById("goto-line-dialog");
  const input = document.getElementById("goto-line-input");
  const kind = dialog?.dataset.kind === "ub" ? "ub" : "expert";
  const max = _bmText(kind).split("\n").length;
  const line = /^\d+$/.test(String(input?.value || "").trim()) ? Number(input.value.trim()) : NaN;
  if (!Number.isInteger(line) || line < 1 || line > max) {
    input?.classList.add("goto-line-input--error");
    return;
  }
  dialog?.close();
  _bmGoto(kind, line - 1);
}

function setupBookmarks() {
  document.getElementById("goto-line-form")?.addEventListener("submit", (e) => {
    e.preventDefault();
    _gotoLineSubmit();
  });
  document.getElementById("goto-line-input")?.addEventListener("input", (e) => e.target.classList.remove("goto-line-input--error"));
  document.getElementById("goto-line-dialog")?.addEventListener("click", (e) => {
    if (e.target.id === "goto-line-dialog") e.target.close();
  });
  for (const kind of ["expert", "ub"]) {
    const on = (name, fn) => document.getElementById(`${kind}-${name}-btn`)?.addEventListener("click", fn);
    on("goto", () => _gotoLineOpen(kind));
    on("bm-toggle", () => { _bmToggle(kind); (kind === "ub" ? ubEditor : expertEditor)?.focus(); });
    on("bm-prev", () => _bmJump(kind, -1));
    on("bm-next", () => _bmJump(kind, 1));
    on("bm-clear", () => _bmSet(kind, []));
  }
}

function _ubRenderProjectSymbols() {
  const container = document.getElementById("ub-project-symbols");
  if (!container || !ubEditor) return;
  const groups = { labels: [], subs: [], functions: [] };
  ubEditor.value.split("\n").forEach((line, lineIndex) => {
    let match = line.match(/^\s*label\s+([A-Za-z_][A-Za-z0-9_]*)\b/i);
    if (match) { groups.labels.push({ name: match[1], lineIndex }); return; }
    match = line.match(/^\s*sub\s+([A-Za-z_][A-Za-z0-9_]*)\b/i);
    if (match) { groups.subs.push({ name: match[1], lineIndex }); return; }
    match = line.match(/^\s*(?:fn|function)\s+([A-Za-z_][A-Za-z0-9_]*)\b/i);
    if (match) groups.functions.push({ name: match[1], lineIndex });
  });
  container.innerHTML = "";
  const icons = {
    labels: `<svg viewBox="0 0 14 14" fill="none" width="12" height="12"><path d="M2 3h7l3 4-3 4H2V3Z" stroke="currentColor" stroke-width="1.1"/><circle cx="4.5" cy="7" r="1" fill="currentColor"/></svg>`,
    subs: `<svg viewBox="0 0 14 14" fill="none" width="12" height="12"><path d="M3 2.5h8v9H3z" stroke="currentColor" stroke-width="1.1"/><path d="M5 5h4M5 7h4M5 9h2" stroke="currentColor" stroke-width="1"/></svg>`,
    functions: `<svg viewBox="0 0 14 14" fill="none" width="12" height="12"><path d="M3 11c2-1 2-7 4-8M4 6h5M8.5 8.5l2.5 2.5M11 8.5 8.5 11" stroke="currentColor" stroke-width="1.1" stroke-linecap="round"/></svg>`
  };
  const labels = { labels: t("projLabels"), subs: t("ubSubs"), functions: t("ubFunctions") };
  Object.entries(groups).forEach(([kind, entries]) => {
    if (!entries.length) return;
    const header = document.createElement("div");
    header.className = "expert-project-symbols-label";
    header.textContent = labels[kind];
    container.appendChild(header);
    entries.forEach(entry => {
      const row = document.createElement("div");
      row.className = "expert-project-item expert-project-item--file";
      row.innerHTML = `<span class="expert-project-item-icon">${icons[kind]}</span>`;
      const name = document.createElement("span");
      name.className = "expert-project-item-name";
      name.textContent = entry.name;
      name.setAttribute("aria-label", `${entry.name} · ${t("ubLine")} ${entry.lineIndex + 1}`);
      row.appendChild(name);
      row.addEventListener("click", () => _ubGotoLine(entry.lineIndex));
      container.appendChild(row);
    });
  });
  if (!container.children.length) {
    const empty = document.createElement("div");
    empty.className = "expert-project-empty";
    empty.textContent = t("ubNoSymbols");
    container.appendChild(empty);
  }
}

function _ubSyncScroll() {
  const code = document.getElementById("ub-highlight-code");
  const gutter = document.getElementById("ub-line-numbers-content");
  if (code) { code.style.display = "block"; code.style.transform = `translate(${-ubEditor.scrollLeft}px, ${-ubEditor.scrollTop}px)`; }
  if (gutter) gutter.style.transform = `translateY(${-ubEditor.scrollTop}px)`;
  _ubUpdateCaret();
  _ubDrawMinimap();
}

function _ubSetToggle(id, on) { const btn = document.getElementById(id); btn?.classList.toggle("expert-hl-toggle--on", on); btn?.setAttribute("aria-pressed", String(on)); }
function _ubToggleHighlight() { _ubHighlightEnabled = !_ubHighlightEnabled; _ubSetToggle("ub-hl-btn", _ubHighlightEnabled); _ubRefreshEditor(); }
// UB build → soronkénti kódköltség a dbg listing-spanokból: Map(0-alapú sor → {bytes, cycles}).
// A ciklus a span utasításainak alapciklus-összege (egyenes futás, ciklusok / elágazások nélkül);
// beágyazott adat (dataRegions) csak bájtként számít.
function _ubLineCost(result) {
  const map = new Map();
  const load = result?.map?.loadAddress;
  const code = result?.map?.codeBytes;
  if (!Number.isFinite(load) || !Array.isArray(code)) return map;
  const data = (result.map.dataRegions || []).map((r) => [r.start, r.end]);
  String(result?.debug?.dbg || "").split("\n").forEach((row) => {
    const m = /^\s*([0-9a-f]{1,4}),([0-9a-f]{1,4}),\d+,(\d+),/i.exec(row);
    if (!m) return;
    const start = parseInt(m[1], 16) - load;
    const end = parseInt(m[2], 16) - load;
    if (start < 0 || end < start || end >= code.length) return;
    const line = Number(m[3]) - 1;
    let cycles = 0;
    if (!data.some(([a, b]) => start < b && end >= a)) {
      for (let p = start; p <= end;) {
        const info = _REV_OP[code[p]];
        if (!info || info.mode === "unknown") { p++; continue; }
        cycles += _OP_CYCLES[code[p]];
        p += info.size;
      }
    }
    const prev = map.get(line) || { bytes: 0, cycles: 0 };
    map.set(line, { bytes: prev.bytes + end - start + 1, cycles: prev.cycles + cycles });
  });
  return map;
}

// ── UB lint ──
// {srcLine, key, values}: sys a KERNAL IRQ-kilépésre (a sys JSR → az RTI szemétre tér vissza), nem
// dokumentált `wait key`, nem használt var/dim/const, és build után asm-blokkbeli ZP-cím, amelyet egy
// UB-változó (vagy a futtatókörnyezet belső ZP-je) is használ.
const _UB_LINT_IRQ_EXITS = new Set([0xEA31, 0xEA81, 0xEA7E, 0xFEBC]);

function _ubLintStrip(line) {
  let out = "", quote = false;
  for (const ch of line) {
    if (ch === "\"") quote = !quote;
    if (!quote && (ch === "#" || ch === "'")) break;
    out += quote ? " " : ch;
  }
  return out;
}

function _ubLint(text, result) {
  const hints = [];
  const lines = String(text || "").split("\n");
  const decls = [];
  const words = new Map();
  let inAsm = false;
  const asmLines = [];
  lines.forEach((raw, i) => {
    if (inAsm) {
      const body = raw.replace(/;.*$/, "");
      if (/^\s*}/.test(body)) inAsm = false;
      else asmLines.push([i, body]);
      return;
    }
    const code = _ubLintStrip(raw);
    const asmOpen = /^\s*asm\s*\{(.*)$/i.exec(code);
    if (asmOpen) {
      const rest = asmOpen[1].replace(/;.*$/, "");
      if (rest.includes("}")) asmLines.push([i, rest.slice(0, rest.indexOf("}"))]);
      else { inAsm = true; if (rest.trim()) asmLines.push([i, rest]); }
      return;
    }
    const sys = /\bsys\s+(\$[0-9a-f]+|\d+)/i.exec(code);
    if (sys) {
      const addr = sys[1][0] === "$" ? parseInt(sys[1].slice(1), 16) : parseInt(sys[1], 10);
      if (_UB_LINT_IRQ_EXITS.has(addr)) hints.push({ srcLine: i, key: "ubLintSysIrqExit", values: { addr: "$" + addr.toString(16).toUpperCase() } });
    }
    if (/\bwait\s+key\b/i.test(code)) hints.push({ srcLine: i, key: "ubLintWaitKey", values: {} });
    const decl = /^\s*(?:var|dim|const)\s+([A-Za-z_][\w]*)/i.exec(code);
    if (decl) decls.push([i, decl[1]]);
    for (const w of code.match(/[A-Za-z_][\w]*\$?/g) || []) {
      const k = w.replace(/\$$/, "").toLowerCase();
      words.set(k, (words.get(k) || 0) + 1);
    }
  });
  asmLines.forEach(([, body]) => {
    for (const w of body.match(/[A-Za-z_][\w]*/g) || []) words.set(w.toLowerCase(), (words.get(w.toLowerCase()) || 0) + 1);
  });
  decls.forEach(([i, name]) => {
    if ((words.get(name.toLowerCase()) || 0) <= 1) hints.push({ srcLine: i, key: "ubLintUnused", values: { name } });
  });
  const zpOwners = new Map();
  (result?.map?.variables || []).forEach((v) => {
    if (Number.isInteger(v.address) && v.address < 0x100) {
      zpOwners.set(v.address, v.name);
      if (/word|int|single|double|string|\$/i.test(String(v.type || "")) && v.address < 0xFF) zpOwners.set(v.address + 1, v.name);
    }
  });
  Object.entries(result?.map?.internal || {}).forEach(([key, addr]) => {
    if (Number.isInteger(addr) && addr < 0xFF && /Zp$/.test(key)) { zpOwners.set(addr, "UB " + key); zpOwners.set(addr + 1, "UB " + key); }
  });
  if (zpOwners.size) {
    asmLines.forEach(([i, body]) => {
      const m = /^\s*(?:[A-Za-z_]\w*:)?\s*[A-Za-z]{3}\s+\(?\$([0-9a-f]{1,2})\b(?!\w)/i.exec(body);
      if (!m) return;
      const addr = parseInt(m[1], 16);
      if (zpOwners.has(addr)) hints.push({ srcLine: i, key: "ubLintZpConflict", values: { addr: "$" + m[1].toUpperCase().padStart(2, "0"), name: zpOwners.get(addr) } });
    });
  }
  return hints;
}

