function _ubApplyFontSize() { document.querySelectorAll(".ub-editor,.ub-highlight,.ub-line-numbers").forEach(el => el.style.fontSize = `${_ubFontSize}px`); _ubRefreshEditor(); }
function _ubZoom(delta) { _ubFontSize = Math.max(8, Math.min(28, _ubFontSize + delta)); _ubApplyFontSize(); saveUiSettings(); }

function _ubOpenFind() {
  document.getElementById("ub-find-bar").hidden = false;
  _ubSetToggle("ub-find-btn", true);
  const input = document.getElementById("ub-find-input");
  const selection = ubEditor?.value.slice(ubEditor.selectionStart, ubEditor.selectionEnd) || "";
  if (selection && selection.length < 80 && !selection.includes("\n")) input.value = selection;
  input.focus(); input.select(); _ubFind(0);
}
function _ubCloseFind() {
  document.getElementById("ub-find-bar").hidden = true;
  _ubSetToggle("ub-find-btn", false);
  _ubFindMatches = []; _ubFindIndex = -1;
  ubEditor.focus();
}
function _ubFind(direction = 0) {
  const term = document.getElementById("ub-find-input")?.value || "";
  _ubFindMatches = [];
  if (term) { let at = 0; const hay = ubEditor.value.toLowerCase(), needle = term.toLowerCase(); while ((at = hay.indexOf(needle, at)) >= 0) { _ubFindMatches.push(at); at += Math.max(1, needle.length); } }
  if (!_ubFindMatches.length) _ubFindIndex = -1;
  else if (direction === 0) _ubFindIndex = 0;
  else _ubFindIndex = (_ubFindIndex + direction + _ubFindMatches.length) % _ubFindMatches.length;
  const count = document.getElementById("ub-find-count");
  if (count) {
    count.textContent = !term ? "" : _ubFindIndex < 0 ? (currentLanguage === "hu" ? "Nincs találat." : currentLanguage === "es" ? "Sin resultados." : currentLanguage === "de" ? "Keine Treffer." : currentLanguage === "nl" ? "Geen resultaten." : currentLanguage === "pl" ? "Brak wyników." : currentLanguage === "it" ? "Nessun risultato." : "No results.") : `${_ubFindIndex + 1} / ${_ubFindMatches.length}`;
    count.style.color = term && _ubFindIndex < 0 ? "var(--error, #f44)" : "";
  }
  if (_ubFindIndex >= 0) {
    const start = _ubFindMatches[_ubFindIndex];
    ubEditor.setSelectionRange(start, start + term.length);
    const line = ubEditor.value.slice(0, start).split("\n").length - 1;
    const lineHeight = parseFloat(getComputedStyle(ubEditor).lineHeight) || 21;
    const paddingTop = parseFloat(getComputedStyle(ubEditor).paddingTop) || 16;
    ubEditor.scrollTop = Math.max(0, paddingTop + line * lineHeight - ubEditor.clientHeight / 2);
    if (direction !== 0) ubEditor.focus();
  }
}

function _ubDrawMinimap() {
  if (!_ubMinimapEnabled) return;
  const canvas = document.getElementById("ub-minimap");
  if (!canvas || !canvas.offsetWidth || !canvas.offsetHeight) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const width = canvas.offsetWidth;
  const height = canvas.offsetHeight;
  const canvasWidth = Math.round(width * dpr);
  const canvasHeight = Math.round(height * dpr);
  if (canvas.width !== canvasWidth || canvas.height !== canvasHeight) {
    canvas.width = canvasWidth;
    canvas.height = canvasHeight;
  }
  const ctx = canvas.getContext("2d");
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

  const rootStyle = getComputedStyle(document.documentElement);
  const background = rootStyle.getPropertyValue("--expert-editor-bg").trim() || "#1a1b26";
  const commentColor = rootStyle.getPropertyValue("--hl-comment").trim() || "#6a9955";
  const keywordColor = rootStyle.getPropertyValue("--hl-mnem").trim() || "#dcdcaa";
  const labelColor = rootStyle.getPropertyValue("--hl-label").trim() || "#9cdcfe";
  const declarationColor = rootStyle.getPropertyValue("--hl-directive").trim() || "#569cd6";
  const numberColor = rootStyle.getPropertyValue("--hl-number").trim() || "#b5cea8";
  const primary = rootStyle.getPropertyValue("--primary").trim() || "#2563eb";
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, width, height);

  const lines = ubEditor.value.split("\n");
  const total = lines.length || 1;
  const linePx = 2;
  const editorLineHeight = ubEditor.scrollHeight / total;
  const topLine = ubEditor.scrollTop / editorLineHeight;
  const visibleLines = ubEditor.clientHeight / editorLineHeight;
  const contentHeight = total * linePx;
  let minimapOffset = 0;
  if (contentHeight > height) {
    const viewportMiddle = (topLine + visibleLines / 2) * linePx;
    minimapOffset = Math.max(0, Math.min(contentHeight - height, viewportMiddle - height / 2));
  }

  const xPadding = 3;
  const maxWidth = width - xPadding * 2;
  lines.forEach((raw, index) => {
    const y = index * linePx - minimapOffset;
    if (y + linePx < 0 || y > height) return;
    const trimmed = raw.trimStart();
    if (!trimmed) return;
    let color = keywordColor;
    if (/^(#|'|rem\b)/i.test(trimmed)) color = commentColor;
    else if (/^[A-Za-z_][A-Za-z0-9_]*:/i.test(trimmed)) color = labelColor;
    else if (/^(var|dim|const|sub|fn|function|label|include|incbin|load|data)\b/i.test(trimmed)) color = declarationColor;
    else if (/^(\d|\$[0-9a-f]|%[01])/i.test(trimmed)) color = numberColor;
    const indent = raw.length - trimmed.length;
    const indentX = Math.min(indent * 1.5, maxWidth * 0.35);
    const barWidth = Math.min(trimmed.length * 1.3, maxWidth - indentX);
    ctx.globalAlpha = 0.72;
    ctx.fillStyle = color;
    ctx.fillRect(xPadding + indentX, y, Math.max(3, barWidth), Math.max(1, linePx - 0.3));
  });
  ctx.globalAlpha = 1;

  const viewportTop = topLine * linePx - minimapOffset;
  const viewportHeight = Math.max(8, visibleLines * linePx);
  ctx.fillStyle = _mmAlphaColor(primary, 0.12);
  ctx.fillRect(0, viewportTop, width, viewportHeight);
  ctx.strokeStyle = _mmAlphaColor(primary, 0.5);
  ctx.lineWidth = 1;
  ctx.strokeRect(0.5, viewportTop + 0.5, width - 1, viewportHeight - 1);
}

function _ubSetStatus(text, error = false) {
  if (!ubStatus) return;
  ubStatus.textContent = text;
  ubStatus.style.color = error ? "var(--error, #f44)" : "";
}

function _ubUpdateCursor() {
  if (!ubEditor) return;
  const lines = ubEditor.value.slice(0, ubEditor.selectionStart).split("\n");
  const el = document.getElementById("ub-cursor-pos");
  const cost = _ubHeatEnabled ? _ubLineCostMap?.get(lines.length - 1) : null;
  if (el) el.textContent = `Ln ${lines.length}, Col ${lines[lines.length - 1].length + 1}` + (cost ? "  ·  " + tf("ubHeatLine", cost) : "");
  _ubUpdateCaret();
}

function _ubUpdateCaret() {
  if (!ubCaret || !ubEditor) return;
  ubCaret.hidden = true;
  if (document.activeElement !== ubEditor || ubEditor.selectionStart !== ubEditor.selectionEnd) return;

  const code = document.getElementById("ub-highlight-code");
  const wrap = ubEditor.closest(".ub-editor-wrap");
  if (!code || !wrap) return;

  let remaining = ubEditor.selectionStart;
  const walker = document.createTreeWalker(code, NodeFilter.SHOW_TEXT);
  let node = walker.nextNode();
  while (node && remaining > node.nodeValue.length) {
    remaining -= node.nodeValue.length;
    node = walker.nextNode();
  }
  if (!node) return;

  const range = document.createRange();
  range.setStart(node, Math.min(remaining, node.nodeValue.length));
  range.collapse(true);
  const marker = document.createElement("span");
  marker.className = "ub-caret-measure";
  marker.textContent = "\u200B";
  range.insertNode(marker);
  const markerRect = marker.getBoundingClientRect();
  marker.remove();
  const wrapRect = wrap.getBoundingClientRect();
  if (!markerRect.width && !markerRect.height) return;

  const editorRect = ubEditor.getBoundingClientRect();
  const caretWidth = ubCaret.offsetWidth || 2;
  const maxLeft = editorRect.right - wrapRect.left - caretWidth;
  ubCaret.style.left = `${Math.min(markerRect.left - wrapRect.left, maxLeft)}px`;
  ubCaret.style.top = `${markerRect.top - wrapRect.top}px`;
  ubCaret.style.height = `${markerRect.height || parseFloat(getComputedStyle(ubEditor).lineHeight) || 21}px`;
  ubCaret.hidden = false;
  ubCaret.style.animation = "none";
  void ubCaret.offsetWidth;
  ubCaret.style.animation = "";
}

function _ubSetFile(path = "") {
  _ubFilePath = path;
  const tab = _getActiveTab();
  if (tab && ultimateBasicMode) {
    tab.ubFilePath = path;
    tab.filePath = path || null;
    tab.name = path ? path.replace(/\\/g, "/").split("/").pop() : tab._untitledName;
    renderTabBar();
    _ubRenderProjectFiles();
  }
  _acmeBuildButtonSync();
  _updateEditorModeIndicator();
}

function _ubRenderProjectFiles() {
  const list = document.getElementById("ub-project-files");
  const projectName = document.getElementById("ub-project-name");
  if (!list) return;
  _projUpdateSaveBtn("ub-project-save-btn", !!_ubProjectData, _ubProjectDirty);
  list.innerHTML = "";
  if (projectName) {
    projectName.textContent = _ubProjectData?.name || t("projNoProject");
    projectName.setAttribute("aria-label", _ubProjectData?._projPath || t("ubNoProjectTooltip"));
  }
  if (!_ubProjectData) {
    list.innerHTML = `<div class="expert-project-empty">${_ubEsc(t("projClickToOpen")).replace("\n", "<br>")}</div>`;
    return;
  }
  const root = document.createElement("div");
  root.className = "expert-project-item expert-project-item--root";
  root.innerHTML = `<span class="expert-project-item-icon">${_PROJ_SVG.project}</span><span class="expert-project-item-name">${_ubEsc(_ubProjectData.name || "UltimateBasic")}</span>`;
  list.appendChild(root);
  if (!_ubProjectData.files.length) {
    const empty = document.createElement("div");
    empty.className = "expert-project-empty";
    empty.textContent = t("ubNoFiles");
    list.appendChild(empty);
    return;
  }
  const moved = () => { _ubTouchProject(); _ubRenderProjectFiles(); };
  const renderNode = (file, container, depth) => {
    const isFolder = file.type === "folder";
    const remove = _makeProjDelBtn(() => {
      const idx = container.indexOf(file);
      if (idx >= 0) container.splice(idx, 1);
      if (_ubProjectData.startupFile === file.path) _ubProjectData.startupFile = null;
      _ubProjectDirty = true;
      _ubRenderProjectFiles();
    });

    if (isFolder) {
      const hasChildren = (file.children || []).length > 0;
      const collapsed = !!file._collapsed;
      const item = document.createElement("div");
      item.className = "expert-project-item expert-project-item--file expert-project-item--folder";
      item.style.paddingLeft = `${8 + depth * 18}px`;
      const toggle = document.createElement("span");
      toggle.className = "expert-project-item-toggle" + (hasChildren ? "" : " expert-project-item-toggle--empty");
      toggle.innerHTML = hasChildren
        ? `<svg viewBox="0 0 10 10" width="9" height="9" style="transform:rotate(${collapsed ? "-90deg" : "0deg"})" aria-hidden="true"><path d="M2 3l3 3 3-3" stroke="currentColor" stroke-width="1.4" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`
        : "";
      const icon = document.createElement("span");
      icon.className = "expert-project-item-icon";
      icon.innerHTML = _PROJ_SVG.project;
      const name = document.createElement("span");
      name.className = "expert-project-item-name";
      name.textContent = file.name;
      name.setAttribute("aria-label", file.path);
      item.append(toggle, icon, name, remove);
      item.addEventListener("click", e => {
        if (remove.contains(e.target)) return;
        if (!hasChildren) return;
        file._collapsed = !file._collapsed;
        _ubRenderProjectFiles();
      });
      item.addEventListener("contextmenu", e => {
        _projShowItemMenu(e, { container, entry: file, onMoved: moved, onAddFile: () => _ubAddFile(file.children || (file.children = [])) });
      });
      list.appendChild(item);
      if (!collapsed) (file.children || []).forEach(child => renderNode(child, file.children, depth + 1));
      return;
    }

    const absPath = _ubResolveProjectPath(file.path);
    const tab = tabs.find(candidate => _normFilePath(candidate.ubFilePath || candidate.filePath) === _normFilePath(absPath));
    const isStartup = _ubProjectData.startupFile === file.path;
    const isUb = /\.ub$/i.test(file.name || file.path || "");
    const item = document.createElement("div");
    item.className = "expert-project-item expert-project-item--file" + (tab?.id === activeTabId ? " expert-project-item--active" : "") + (isStartup ? " expert-project-item--startup" : "") + (tab?.dirty ? " ub-project-file-dirty" : "");
    item.style.paddingLeft = `${8 + depth * 18 + (depth > 0 ? 14 : 0)}px`;
    const icon = document.createElement("span");
    icon.className = "expert-project-item-icon";
    icon.innerHTML = isUb
      ? `<svg viewBox="0 0 16 16" fill="none" width="12" height="12" aria-hidden="true"><path d="M3 2h7l3 3v9H3V2Z" stroke="currentColor" stroke-width="1.1"/><path d="M10 2v3h3" stroke="currentColor" stroke-width="1"/></svg>`
      : _projFileIcon(file.name);
    const name = document.createElement("span");
    name.className = "expert-project-item-name";
    name.textContent = file.name;
    name.setAttribute("aria-label", file.path);
    const startup = document.createElement("button");
    startup.type = "button";
    startup.className = "expert-project-item-star" + (isStartup ? " expert-project-item-star--on" : "");
    startup.setAttribute("aria-label", isStartup ? t("projUnsetStartup") : t("projSetStartup"));
    startup.innerHTML = `<svg viewBox="0 0 14 14" fill="${isStartup ? "currentColor" : "none"}" width="11" height="11" aria-hidden="true"><path d="M7 1 8.5 5.5H13L9.5 8.5 11 13 7 10 3 13 4.5 8.5 1 5.5h4.5L7 1Z" stroke="currentColor" stroke-width="${isStartup ? ".5" : "1"}" opacity="${isStartup ? "1" : ".5"}"/></svg>`;
    startup.addEventListener("click", (event) => {
      event.stopPropagation();
      _ubProjectData.startupFile = isStartup ? null : file.path;
      _ubProjectDirty = true;
      _ubRenderProjectFiles();
    });
    item.append(icon, name, startup, remove);
    item.addEventListener("click", event => {
      if (startup.contains(event.target) || remove.contains(event.target)) return;
      if (tab) _tabActivate(tab.id);
      else if (isUb) _ubOpenProjectFile(file);
    });
    item.addEventListener("contextmenu", e => _projShowItemMenu(e, { container, entry: file, onMoved: moved }));
    list.appendChild(item);
  };

  _ubProjectData.files.forEach(file => renderNode(file, _ubProjectData.files, 0));
}

function _ubResolveProjectPath(path) {
  if (!path || /^[A-Za-z]:[\\/]/.test(path) || path.startsWith("/")) return path;
  const projectPath = (_ubProjectData?._projPath || "").replace(/\\/g, "/");
  const slash = projectPath.lastIndexOf("/");
  return slash >= 0 ? `${projectPath.slice(0, slash)}/${path}` : path;
}

function _ubProjectRelativePath(path) {
  const normalized = (path || "").replace(/\\/g, "/");
  const projectPath = (_ubProjectData?._projPath || "").replace(/\\/g, "/");
  const slash = projectPath.lastIndexOf("/");
  const dir = slash >= 0 ? projectPath.slice(0, slash) : "";
  return dir && normalized.startsWith(`${dir}/`) ? normalized.slice(dir.length + 1) : normalized;
}

function _ubAddProjectFile(path) {
  if (!_ubProjectData || !path) return;
  const relPath = _ubProjectRelativePath(path);
  if (!_ubProjectData.files.some(file => _normFilePath(_ubResolveProjectPath(file.path)) === _normFilePath(path))) {
    _ubProjectData.files.push({ type: "file", name: path.replace(/\\/g, "/").split("/").pop(), path: relPath });
    _ubProjectDirty = true;
  }
  _ubRenderProjectFiles();
}

// Unified "Add file" — any file type, multi-select. A .ub file is also opened as
// an editor tab; anything else (fonts, sprites, other binary assets) is added as
// a reference only.
async function _ubAddFile(intoContainer = null) {
  const res = await window.electronAPI?.chooseProjMember?.(true);
  if (!res || res.canceled || !res.files?.length) return;
  if (!_ubProjectData) _ubProjectData = { name: "New UltimateBasic project", files: [], startupFile: null, _projPath: null };
  const container = intoContainer || _ubProjectData.files;
  let openedCount = 0;
  for (const f of res.files) {
    const isUb = /\.ub$/i.test(f.fileName || f.filePath || "");
    if (isUb && !intoContainer) {
      const read = await window.electronAPI?.readTextFile?.(f.filePath);
      if (!read?.ok) { _ubSetStatus(read?.error || "Open failed", true); continue; }
      _ubCreateFileTab(f.filePath, read.content || "");
      openedCount++;
    }
    const relPath = _ubProjectRelativePath(f.filePath);
    if (!container.some(file => file.type !== "folder" && _normFilePath(_ubResolveProjectPath(file.path)) === _normFilePath(f.filePath))) {
      container.push({ type: "file", name: f.fileName, path: relPath });
      _ubProjectDirty = true;
    }
  }
  _ubSetStatus(openedCount > 0 ? t("ubLoaded") : t("ubProjectSaved"));
  _ubRenderProjectFiles();
}

async function _ubAddProjectFolder() {
  const res = await window.electronAPI?.chooseProjFolder?.(true);
  if (!res || res.canceled) return;
  if (!_ubProjectData) _ubProjectData = { name: "New UltimateBasic project", files: [], startupFile: null, _projPath: null };
  const relPath = _ubProjectRelativePath(res.folderPath);
  if (!_ubProjectData.files.some(file => file.type === "folder" && _normFilePath(_ubResolveProjectPath(file.path)) === _normFilePath(res.folderPath))) {
    _ubProjectData.files.push({ type: "folder", name: res.folderName, path: relPath, children: [] });
    _ubProjectDirty = true;
  }
  _ubRenderProjectFiles();
}

async function _ubOpenProjectFile(file) {
  const path = _ubResolveProjectPath(file.path);
  const result = await window.electronAPI?.readTextFile?.(path);
  if (!result?.ok) { _ubSetStatus(result?.error || "Unable to open project file", true); return; }
  return _ubCreateFileTab(path, result.content || "");
}

function _ubCreateFileTab(path, content) {
  const existing = tabs.find(tab => _normFilePath(tab.ubFilePath || tab.filePath) === _normFilePath(path));
  if (existing) { _tabActivate(existing.id); return existing; }
  _tabSaveCurrent();
  const fileName = path.replace(/\\/g, "/").split("/").pop() || "program.ub";
  const tab = _tabCreate(fileName);
  Object.assign(tab, { editorMode: "ub", ubText: content, ubFilePath: path, filePath: path, program: [makeDefaultOrgBlock()] });
  tabs.push(tab);
  activeTabId = tab.id;
  program = JSON.parse(JSON.stringify(tab.program));
  userMacros = {};
  selectedBlockId = null;
  if (!ultimateBasicMode) setUltimateBasicMode(true);
  ubEditor.value = content;
  _ubEditorTabId = tab.id; // _tabSaveCurrent keeps the editor's text only for this tab
  _ubBreakpointLines = [];
  _ubFilePath = path;
  _ubDirty = false;
  updateWindowTitle(fileName);
  _ubRefreshEditor();
  renderTabBar();
  _ubRenderProjectFiles();
  _historyResetCurrent();
  ubEditor?.focus();
  return tab;
}

async function _ubOpenProject() {
  const result = await window.electronAPI?.openProjFile?.(ubWorkingFolder);
  if (!result || result.canceled) return;
  if (!result.ok) { _ubSetStatus(result.error || "Project open failed", true); return; }
  const project = result.project || {};
  _ubProjectData = { name: project.name || "UltimateBasic", files: (project.files || []).filter(file => !file.type || file.type === "file" || file.type === "folder"), startupFile: project.startupFile || null, _projPath: result.filePath };
  _ubProjectDirty = false;
  _ubRenderProjectFiles();
  const startup = _projFindEntry(_ubProjectData.files, _ubProjectData.startupFile);
  if (startup) await _ubOpenProjectFile(startup);
  _ubSetStatus(`${t("ubProjectOpened")}: ${_ubProjectData.name}`);
}

async function _ubNewProject() {
  _ubProjectData = { name: "New UltimateBasic project", files: [], startupFile: null, _projPath: null };
  _ubRenderProjectFiles();
  await _ubSaveProject();
}

async function _ubSaveProject() {
  if (!_ubProjectData) { await _ubNewProject(); return; }
  const wasNew = !_ubProjectData._projPath;
  const payload = JSON.stringify({ app: "ultimate-basic", name: _ubProjectData.name, files: _ubProjectData.files, startupFile: _ubProjectData.startupFile || null }, null, 2);
  const result = await window.electronAPI?.saveProjFile?.(_ubProjectData._projPath || "", payload, ubWorkingFolder);
  if (!result || result.canceled) return;
  if (!result.ok) { _ubSetStatus(result.error || "Project save failed", true); return; }
  _ubProjectData._projPath = result.filePath;
  _ubProjectData.files.forEach(file => { file.path = _ubProjectRelativePath(_ubResolveProjectPath(file.path)); });
  if (_ubProjectData.name === "New UltimateBasic project") _ubProjectData.name = result.filePath.replace(/\\/g, "/").split("/").pop().replace(/\.proj$/i, "");
  if (wasNew) {
    const portablePayload = JSON.stringify({ app: "ultimate-basic", name: _ubProjectData.name, files: _ubProjectData.files, startupFile: _ubProjectData.startupFile || null }, null, 2);
    const rewrite = await window.electronAPI?.saveProjFile?.(_ubProjectData._projPath, portablePayload, ubWorkingFolder);
    if (!rewrite?.ok) { _ubSetStatus(rewrite?.error || "Project save failed", true); return; }
  }
  _ubProjectDirty = false;
  _ubRenderProjectFiles();
  _ubSetStatus(t("ubProjectSaved"));
}

function _ubRenderCommandReference() {
  const list = document.getElementById("ub-command-list");
  const detail = document.getElementById("ub-command-detail");
  if (!list || !detail) return;
  const term = (document.getElementById("ub-command-search")?.value || "").trim().toLowerCase();
  // Command names first (prefix, then substring); syntax and descriptions only on a
  // word start, so "map" does not list everything that mentions "bitmap".
  const wordStart = term ? new RegExp("(^|[^a-z0-9_])" + term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) : null;
  const rank = ([name, syntax, description]) => {
    if (!term) return 0;
    if (name.startsWith(term)) return 0;
    if (name.includes(term)) return 1;
    if (wordStart.test(syntax.toLowerCase())) return 2;
    const desc = _ubGetCommandDescription(name) || description;
    return wordStart.test(desc.toLowerCase()) ? 3 : -1;
  };
  const matches = _UB_COMMAND_REFERENCE
    .map((entry, index) => ({ entry, index, score: rank(entry) }))
    .filter((item) => item.score >= 0)
    .sort((a, b) => a.score - b.score || a.index - b.index)
    .map((item) => item.entry);
  list.innerHTML = "";
  matches.forEach(([name]) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "ub-command-item palette-item" + (name === _ubSelectedCommand ? " ub-command-item--active palette-item--active" : "");
    const command = _UB_COMMAND_REFERENCE.find(([commandName]) => commandName === name);
    const mnemonic = document.createElement("strong");
    mnemonic.className = "palette-mnemonic";
    mnemonic.textContent = name;
    const summary = document.createElement("span");
    summary.className = "palette-description";
    summary.textContent = command?.[1]?.split("\n")[0] || "";
    button.append(mnemonic, summary);
    button.addEventListener("click", () => { _ubSelectedCommand = name; _ubRenderCommandReference(); });
    list.appendChild(button);
  });
  if (!matches.length) {
    list.textContent = t("ubNoMatchingCommands");
    detail.innerHTML = `<code>${t("ubNoCommandSelected")}</code><p>${t("ubTryDifferentSearch")}</p>`;
    return;
  }
  let selected = matches.find(([name]) => name === _ubSelectedCommand);
  if (!selected) { selected = matches[0]; _ubSelectedCommand = selected[0]; }
  detail.innerHTML = "";
  const title = document.createElement("strong");
  title.className = "ub-command-detail-title";
  title.textContent = selected[0].toUpperCase();
  const descriptionLabel = document.createElement("span");
  descriptionLabel.className = "mnemonic-field-label";
  descriptionLabel.textContent = t("ubDescriptionLabel");
  const description = document.createElement("p");
  description.textContent = _ubGetCommandDescription(selected[0]) || selected[2];
  const syntaxLabel = document.createElement("span");
  syntaxLabel.className = "mnemonic-field-label";
  syntaxLabel.textContent = t("ubSyntaxLabel");
  const syntax = document.createElement("code");
  syntax.textContent = selected[1];
  const noteLabel = document.createElement("span");
  noteLabel.className = "mnemonic-field-label";
  noteLabel.textContent = t("ubUsageLabel");
  const note = document.createElement("small");
  // a block has a closing line (end / next / until / endtype ...), not just several examples
  const isBlock = /\n\s*(end|next|until|endtype|endw)\b/i.test(selected[1]);
  note.textContent = isBlock ? t("ubBlockCommandHint") : t("ubSingleCommandHint");
  detail.append(title, descriptionLabel, description, syntaxLabel, syntax, noteLabel, note);
}

function _ubNew() {
  _tabNew();
  if (ubBuildOutput) ubBuildOutput.textContent = "Ready.";
  _ubSetStatus(t("ubNewSource"));
  _ubRefreshEditor();
  ubEditor.focus();
}

async function _ubOpen(addToProject = false) {
  let result;
  try {
    result = await window.electronAPI?.chooseUbFile?.(ubWorkingFolder);
  } catch (error) {
    _ubSetStatus(error?.message || String(error) || "Open failed", true);
    return;
  }
  if (!result || result.canceled) return;
  if (!result.ok) { _ubSetStatus(result.error || "Open failed", true); return; }
  const tab = _ubCreateFileTab(result.filePath || "", result.content || "");
  if (addToProject) {
    if (!_ubProjectData) _ubProjectData = { name: "New UltimateBasic project", files: [], startupFile: null, _projPath: null };
    _ubAddProjectFile(result.filePath || "");
  }
  _ubSetStatus(t("ubLoaded"));
  _ubRefreshEditor();
  renderTabBar();
  _ubRenderProjectFiles();
  ubEditor?.focus();
}

async function _ubSave(forceSaveAs = false) {
  const result = await window.electronAPI?.saveUbFile?.(forceSaveAs ? "" : _ubFilePath, ubEditor.value);
  if (!result || result.canceled) return false;
  if (!result.ok) { _ubSetStatus(result.error || "Save failed", true); return false; }
  _ubSetFile(result.filePath || _ubFilePath);
  _ubDirty = false;
  const tab = _getActiveTab();
  if (tab) { tab.ubText = ubEditor.value; tab.dirty = false; }
  renderTabBar();
  _ubSetStatus(t("ubSaved"));
  return true;
}

let _ubLastResult = null;
let _ubBreakpointLines = [];

function _getTabBreakpointLines(kind) {
  const tab = _getActiveTab();
  const key = kind === "ub" ? "ubBreakpointLines" : "expertBreakpointLines";
  return tab && Array.isArray(tab[key]) ? tab[key] : (kind === "ub" ? _ubBreakpointLines : _expertBreakpointLines);
}

function _setBreakpointLine(kind, line) {
  const key = kind === "ub" ? "ubBreakpointLines" : "expertBreakpointLines";
  const current = new Set(_getTabBreakpointLines(kind));
  if (current.has(line)) current.delete(line); else current.add(line);
  const lines = [...current].filter(Number.isInteger).sort((a, b) => a - b);
  if (kind === "ub") _ubBreakpointLines = lines; else _expertBreakpointLines = lines;
  const tab = _getActiveTab();
  if (tab) tab[key] = lines;
  markTabDirty();
  if (kind === "ub") _ubRefreshEditor(); else _expertUpdateLineNumbers();
}

function _breakpointLinesFromBlocks(blocks) {
  const lines = [];
  let sourceLine = 0;
  (blocks || []).forEach(block => {
    if (block?.isBreakpoint) lines.push(sourceLine);
    sourceLine += Math.max(1, _blockToExpertLine(block).split("\n").length);
  });
  return lines;
}

function _applyExpertBreakpointsToBlocks(blocks) {
  const breakpointLines = new Set(_getTabBreakpointLines("expert"));
  (blocks || []).forEach(block => {
    block.isBreakpoint = typeof block._srcLine === "number" && breakpointLines.has(block._srcLine);
  });
}

function _breakpointAddressForSourceLines(layout, sourceLines) {
  // an included block's _srcLine is a line of its own file, not of the edited source
  const executable = (layout?.lines || []).filter(line => line.size > 0 && !line.conditionallySkipped
    && !line.block?._fromInclude && !line.block?._macroInclude);
  return sourceLines.map(sourceLine => {
    const exact = executable.find(line => line.block?._srcLine === sourceLine);
    const next = executable.find(line => typeof line.block?._srcLine === "number" && line.block._srcLine > sourceLine);
    return (exact || next)?.address;
  }).filter(Number.isFinite).map(address => address & 0xFFFF);
}

function _ubBreakpointAddresses(build, sourceLines) {
  const entries = [];
  String(build?.debug?.dbg || "").split("\n").forEach(line => {
    const match = line.match(/^\s*\$?([0-9a-f]{1,4}),\$?([0-9a-f]{1,4}),\d+,([0-9]+),/i);
    if (match) entries.push({ address: parseInt(match[1], 16), line: Number(match[3]) - 1 });
  });
  return sourceLines.map(sourceLine => {
    const exact = entries.find(entry => entry.line === sourceLine);
    const next = entries.find(entry => entry.line > sourceLine);
    return (exact || next)?.address;
  }).filter(Number.isFinite).map(address => address & 0xFFFF);
}

function _ubRenderDisassembly(result) {
  const output = document.getElementById("ub-disasm-output");
  if (!output) return;
  const bytes = result?.map?.codeBytes;
  const baseAddr = result?.map?.loadAddress;
  if (!Array.isArray(bytes) || !bytes.length || !Number.isFinite(baseAddr)) {
    output.textContent = "Build the source to generate disassembly.";
    return;
  }
  const namesByAddress = new Map();
  String(result?.debug?.sym || "").split("\n").forEach(line => {
    const match = line.match(/^\s*\.label\s+([A-Za-z_][A-Za-z0-9_]*)\s*=\s*\$([0-9a-f]{1,4})\s*$/i);
    if (!match) return;
    const address = parseInt(match[2], 16);
    const names = namesByAddress.get(address) || [];
    if (!names.includes(match[1])) names.push(match[1]);
    namesByAddress.set(address, names);
  });
  [...(result.map.labels || []), ...(result.map.subroutines || [])].forEach(entry => {
    if (!Number.isFinite(entry.address) || !entry.name) return;
    const names = namesByAddress.get(entry.address) || [];
    if (!names.includes(entry.name)) names.push(entry.name);
    namesByAddress.set(entry.address, names);
  });
  const labelByAddress = new Map([...namesByAddress].map(([address, names]) => [address, names[0]]));
  const lines = _buildBasicStubDisasmLines(_getUbBasicStubSection(result));
  _disasmBytes(bytes, baseAddr).forEach(instr => {
    const labels = namesByAddress.get(instr.address);
    if (labels?.length) lines.push(...labels.map(name => `<span class="asm-tok-label">${_ubEsc(name)}:</span>`));
    const address = instr.address.toString(16).toUpperCase().padStart(4, "0");
    const hexBytes = instr.bytes.map(value => value.toString(16).toUpperCase().padStart(2, "0")).join(" ").padEnd(9, " ");
    const operand = String(instr.operand || "").replace(/\$([0-9A-Fa-f]{4})\b/g, (match, hex) => labelByAddress.get(parseInt(hex, 16)) || match);
    const operandHtml = operand ? `  <span class="asm-tok-operand">${_ubEsc(operand)}</span>` : "";
    lines.push(`<span class="dsm-addr">$${address}</span>  <span class="dsm-bytes">${hexBytes}</span>  <span class="asm-tok-mnemonic">${_ubEsc(instr.mnemonic)}</span>${operandHtml}`);
  });
  output.innerHTML = lines.join("\n");
}

function _getUbBasicStubSection(result) {
  return showBasicStubToggle?.checked ? _extractBasicStubSection(result?.prg) : null;
}

function _ubRenderMonitor(result) {
  const output = document.getElementById("ub-monitor-output");
  if (!output) return;
  const bytes = result?.map?.codeBytes;
  const baseAddress = result?.map?.loadAddress;
  if (!Array.isArray(bytes) || !bytes.length || !Number.isFinite(baseAddress)) {
    output.textContent = t("ubMonitorBuildHint");
    return;
  }

  const memMap = new Map();
  const stubSection = _getUbBasicStubSection(result);
  if (stubSection) {
    stubSection.bytes.forEach((byte, index) => memMap.set(stubSection.address + index, byte));
  }
  bytes.forEach((byte, index) => memMap.set(baseAddress + index, byte));
  output.textContent = _formatMonitorMemory(memMap, baseAddress);
}

function _ubFormatMap(map) {
  if (!map) return t("ubBuildSuccessful");
  const hex = (value, width = 4) => `$${Number(value || 0).toString(16).toUpperCase().padStart(width, "0")}`;
  const lines = [`${t("ubBuildSuccessful")} — ${map.codeSize} code bytes`, `${t("ubLoadAddress")}: ${hex(map.loadAddress)}`];
  if (map.variables?.length) lines.push("", "Variables:", ...map.variables.map(v => `  ${v.name.padEnd(16)} ${hex(v.address, 2)}  ${v.type}`));
  if (map.subroutines?.length) lines.push("", "Subroutines:", ...map.subroutines.map(s => `  ${s.name.padEnd(16)} ${hex(s.address)}`));
  if (map.arrays?.length) lines.push("", "Arrays:", ...map.arrays.map(a => `  ${a.name.padEnd(16)} ${hex(a.address)}  ${a.size} bytes`));
  if (_ubVerbose) {
    const internal = map.internal || {};
    const entries = [["plot", internal.plotZp], ["line", internal.lineZp], ["rect", internal.rectZp], ["data", internal.dataZp]].filter(([, value]) => value !== null && value !== undefined);
    lines.push("", "Internal allocations:");
    if (entries.length) lines.push(...entries.map(([name, value]) => `  ${name.padEnd(16)} ZP:${hex(value, 2)}`));
    else lines.push("  (none)");
    if (internal.sinTableAddress !== null && internal.sinTableAddress !== undefined) lines.push(`  ${"sin table".padEnd(16)} ${hex(internal.sinTableAddress)}`);
    const bytes = map.codeBytes || [];
    lines.push("", `Code hex dump (${bytes.length} bytes):`);
    for (let i = 0; i < bytes.length; i += 16) lines.push(`  ${hex((map.loadAddress || 0) + i)}  ${bytes.slice(i, i + 16).map(b => Number(b).toString(16).toUpperCase().padStart(2, "0")).join(" ")}`);
  }
  return lines.join("\n");
}

function _ubSetBuildOutput(text, error = false) {
  if (!ubBuildOutput) return;
  ubBuildOutput.textContent = text;
  ubBuildOutput.classList.toggle("ub-build-output--error", error);
}

function _ubApplyD64LoadAddresses(source) {
  const addresses = new Map();
  const pattern = /^\s*load\s+"([^"]+)"\s*,\s*(\$[0-9a-f]+|\d+)\s*(?:#.*)?$/gim;
  let match;
  while ((match = pattern.exec(String(source || ""))) !== null) {
    const raw = match[2];
    const address = raw.startsWith("$") ? parseInt(raw.slice(1), 16) : parseInt(raw, 10);
    if (Number.isFinite(address) && address >= 0 && address <= 0xFFFF) {
      addresses.set(match[1].toUpperCase(), address.toString(16).toUpperCase().padStart(4, "0"));
    }
  }
  d64ExportState.extras.forEach(extra => {
    const address = addresses.get(String(extra.name || "").toUpperCase());
    if (address) extra.loadAddress = address;
  });
}

function _ubShowCompileErrors(errors) {
  const list = (errors || []).map(error => {
    const text = typeof error === "string" ? error : (error?.text || error?.message || String(error));
    const match = text.match(/(?:line|sor)\s*(\d+)/i);
    return { text, sourceLine: match ? Math.max(0, Number(match[1]) - 1) : undefined };
  });
  _ubOutputVisible = true;
  ubPanel?.classList.remove("ub-hide-output");
  _ubSetToggle("ub-output-btn", true);
  saveUiSettings();
  hideWorkProgress();
  showCompileErrorDialog(list);
}

function _ubCompileSourcePath(sourcePath) {
  if (sourcePath) return sourcePath;
  if (!ubWorkingFolder) return null;
  const separator = ubWorkingFolder.includes("\\") ? "\\" : "/";
  return `${ubWorkingFolder.replace(/[\\/]+$/, "")}${separator}program.ub`;
}

function _ubBuildSidecars(build) {
  const includeDebug = !!writeDebugSidecarsToggle?.checked;
  const includeAsm = !!ubAsmSidecarToggle?.checked;
  if (!includeDebug && !includeAsm) return null;
  return {
    dbg: includeDebug ? build?.debug?.dbg || null : null,
    sym: includeDebug ? build?.debug?.sym || null : null,
    vs: includeDebug ? build?.debug?.vs || null : null,
    asm: includeAsm ? build?.asm || null : null
  };
}

async function _ubApplyExomizer(result, label = "ultimate-basic") {
  if (!exomizerEnabled) return true;
  if (!window.electronAPI?.buildExomizerPrg) {
    _ubSetBuildOutput("Exomizer is not available.", true);
    _ubSetStatus("Exomizer is not available.", true);
    _ubShowCompileErrors(["Exomizer is not available."]);
    return false;
  }
  let packed;
  try {
    packed = await window.electronAPI.buildExomizerPrg({
      bytes: Array.from(result.prg || []),
      fileName: `${String(label).replace(/[^A-Za-z0-9_-]+/g, "-")}-${Date.now()}.prg`,
      sidecars: result.debug || null
    });
  } catch (error) {
    packed = { ok: false, error: error?.message || String(error) };
  }
  if (!packed?.ok) {
    const message = _exomizerErrorMessage(packed?.error, result.prg);
    _ubSetBuildOutput(message, true);
    _ubSetStatus(message, true);
    _ubShowCompileErrors([message]);
    _ubShowCompileErrors([message]);
    return false;
  }
  result.outputPrg = Array.from(packed.bytes || []);
  result.exomizerFilePath = packed.filePath || "";
  return true;
}

async function _ubCompile(showProgress = false, options = {}) {
  _ubSetStatus("Building…");
  if (showProgress) await showWorkProgress("ubBuildProgress", { indeterminate: true });
  setWorkStep("stepUb", { file: _workStepName(_ubFilePath) || "main.ub" });
  let result;
  try {
    result = await window.electronAPI?.compileUltimateBasic?.(ubEditor.value, _ubCompileSourcePath(_ubFilePath), _ubExplicit);
  } catch (error) {
    if (showProgress) hideWorkProgress();
    const message = error?.message || String(error) || "Compilation failed";
    _ubSetBuildOutput(message, true);
    _ubSetStatus(message, true);
    return null;
  }
  _ubLastResult = result;
  _ubLineCostMap = null;
  if (_ubHeatEnabled) _ubRefreshEditor();
  _ubScheduleLint();
  const buildTab = _getActiveTab();
  if (buildTab) buildTab._ubBuildResult = result;
  _ubRenderDisassembly(result);
  _ubRenderMonitor(result);
  renderMemoryMap();
  if (!result?.ok) {
    if (showProgress) hideWorkProgress();
    const errors = result?.errors || [result?.error || "Compilation failed"];
    _ubSetBuildOutput(errors.join("\n"), true);
    _ubSetStatus(`${errors.length} error(s)`, true);
    _ubShowCompileErrors(errors);
    const match = String(errors[0] || "").match(/(?:line|sor)\s*(\d+)/i);
    if (match) {
      const line = Math.max(1, Number(match[1]));
      const start = ubEditor.value.split("\n").slice(0, line - 1).join("\n").length + (line > 1 ? 1 : 0);
      const end = ubEditor.value.indexOf("\n", start);
      ubEditor.focus();
      ubEditor.setSelectionRange(start, end < 0 ? ubEditor.value.length : end);
    }
    return null;
  }
  const buildName = _ubFilePath.split(/[\\/]/).pop()?.replace(/\.ub$/i, "") || "ultimate-basic";
  if (!options.skipExomizer && !(await _ubApplyExomizer(result, buildName))) {
    if (showProgress) hideWorkProgress();
    return null;
  }
  const packedInfo = result.outputPrg ? `\nExomizer: ${result.prg.length} → ${result.outputPrg.length} bytes\n${result.exomizerFilePath}` : "";
  _ubSetBuildOutput(_ubFormatMap(result.map) + packedInfo);
  _ubSetStatus(`${t("ubBuildSuccessful")} — ${(result.outputPrg || result.prg).length} PRG bytes${result.outputPrg ? " (Exomizer)" : ""}`);
  if (showProgress) await completeWorkProgress("ubBuildProgressDone", 650);
  return result;
}

// What a UB build compiles: the project's starred file, open or not; the active tab when
// nothing is starred or the tab is outside the project.
async function _ubBuildTarget() {
  const current = { source: ubEditor?.value || "", path: _ubFilePath || null, startup: false };
  const entry = _projFindEntry(_ubProjectData?.files, _ubProjectData?.startupFile);
  if (!entry) return current;
  const inProject = (nodes, norm) => (nodes || []).some(n => n.type === "folder"
    ? inProject(n.children, norm) : _normFilePath(_ubResolveProjectPath(n.path)) === norm);
  const active = tabs.find(tab => tab.id === activeTabId);
  const activeNorm = _normFilePath(active?.ubFilePath || active?.filePath || _ubFilePath);
  if (!activeNorm || !inProject(_ubProjectData.files, activeNorm)) return current;
  const path = _ubResolveProjectPath(entry.path);
  if (_normFilePath(path) === activeNorm) return current;
  const tab = _findTabByPath(path);
  if (tab) return { source: tab.ubText || "", path, name: tab.name, startup: true, breakpoints: tab.ubBreakpointLines };
  const file = await window.electronAPI?.readTextFile?.(path);
  if (!file?.ok) return { error: tf("projStartupMissing", { file: entry.name || entry.path }) };
  return { source: file.content || "", path, name: entry.name, startup: true };
}

function _ubCompileTarget(target, options = {}) {
  return target.startup ? _ubCompileSource(target.source, target.path, target.name, options) : _ubCompile(false, options);
}

async function _ubRun(mode) {
  const target = await _ubBuildTarget();
  if (target.error) { _ubSetStatus(target.error, true); return; }
  const { source } = target;
  if (!source.trim()) { _ubSetStatus(t("ubNothingToRun"), true); return; }
  const usesUltimate = mode === "ultimate" || mode === "ultimate-d64";
  const usesKff2 = mode === "kff2";
  const usesUe2 = mode === "ue2" || mode === "ue2-d64";
  const host = usesUltimate ? (document.getElementById("ultimate-host")?.value || ultimateHost).trim() : "";
  const kff2PortValue = usesKff2 ? (document.getElementById("kff2-port")?.value || kff2Port).trim() : "";
  if (usesUltimate && !host) { _ubSetStatus(t("ultimateNotConfigured"), true); return; }
  if (usesKff2 && !kff2PortValue) { _ubSetStatus(t("kff2NotConfigured"), true); return; }
  if (!usesUltimate && !usesKff2 && !usesUe2 && !vicePath) { _ubSetStatus(t("viceIsNotConfiguredSelectItInTheMenuFirs"), true); return; }

  await showWorkProgress("ubRunProgress");
  let success = false;
  try {
    setWorkProgress(18);
    const build = await _ubCompileTarget(target);
    if (!build) return;
    setWorkProgress(exomizerEnabled ? 78 : 70);

    if (mode === "d64" || mode === "ultimate-d64" || mode === "ue2-d64") {
      _ubApplyD64LoadAddresses(source);
      hideWorkProgress();
      await openD64ExportDialog(build.outputPrg || build.prg, _ubBuildSidecars(build), mode === "ultimate-d64" ? "ultimate" : mode === "ue2-d64" ? "ue2" : true);
      _ubSetStatus(mode === "ultimate-d64" || mode === "ue2-d64" ? "Ultimate D64 ready" : "D64 ready");
      return;
    }

    let result;
    if (mode === "ultimate") {
      const password = (document.getElementById("ultimate-password")?.value || ultimatePassword).trim() || null;
      result = await window.electronAPI?.runOnUltimate(host, password, build.outputPrg || build.prg);
      _ubSetStatus(result?.ok ? "Running on Ultimate ✓" : (result?.error || "Ultimate run failed"), !result?.ok);
    } else if (mode === "kff2") {
      result = await window.electronAPI?.runOnKff2(kff2PortValue, build.outputPrg || build.prg);
      _ubSetStatus(result?.ok ? "Running on Kung Fu Flash ✓" : (result?.error || t("kff2RunFailed")), !result?.ok);
    } else if (mode === "ue2") {
      setWorkStep("stepUe2", { bytes: (build.outputPrg || build.prg).length });
      result = await window.electronAPI?.ue2RunPrg(Array.from(build.outputPrg || build.prg));
      _ubSetStatus(result?.ok ? t("workProgressSuccessUe2") : _ue2ErrorText(result), !result?.ok);
      _ue2RefreshSettings();
    } else {
      result = await window.electronAPI?.launchVice?.({ bytes: build.outputPrg || build.prg, fileName: `ultimate-basic-${Date.now()}.prg`, sidecars: _ubBuildSidecars(build) });
      _ubSetStatus(result?.ok ? "Running in VICE ✓" : (result?.error || "VICE launch failed"), !result?.ok);
    }
    if (!result?.ok) return;
    setWorkProgress(100);
    success = true;
  } catch (error) {
    const message = error?.message || String(error) || "UltimateBasic run failed";
    _ubSetBuildOutput(message, true);
    _ubSetStatus(message, true);
  } finally {
    if (success) await completeWorkProgress("ubRunProgressDone");
    else hideWorkProgress();
  }
}

async function _ubCompileSource(source, sourcePath, label = "startup file", options = {}) {
  _ubSetStatus(`Building ${label}…`);
  setWorkStep("stepUb", { file: _workStepName(sourcePath) || label });
  const result = await window.electronAPI?.compileUltimateBasic?.(source, _ubCompileSourcePath(sourcePath), _ubExplicit);
  _ubLastResult = result;
  _ubLineCostMap = null;
  if (_ubHeatEnabled) _ubRefreshEditor();
  _ubScheduleLint();
  const sourceTab = sourcePath ? _findTabByPath(sourcePath) : null;
  if (sourceTab) sourceTab._ubBuildResult = result;
  _ubRenderDisassembly(result);
  _ubRenderMonitor(result);
  renderMemoryMap();
  if (!result?.ok) {
    const errors = result?.errors || [result?.error || "Compilation failed"];
    _ubSetBuildOutput(errors.join("\n"), true);
    _ubSetStatus(`${label}: ${errors.length} error(s)`, true);
    _ubShowCompileErrors(errors);
    return null;
  }
  if (!options.skipExomizer && !(await _ubApplyExomizer(result, label))) return null;
  const packedInfo = result.outputPrg ? `\nExomizer: ${result.prg.length} → ${result.outputPrg.length} bytes\n${result.exomizerFilePath}` : "";
  _ubSetBuildOutput(`${label}\n\n${_ubFormatMap(result.map)}${packedInfo}`);
  _ubSetStatus(`${label}: build successful — ${(result.outputPrg || result.prg).length} PRG bytes${result.outputPrg ? " (Exomizer)" : ""}`);
  return result;
}

function _ubDebuggerSymbols(build) {
  const unique = new Map();
  const map = build?.map || {};
  [...(map.labels || []), ...(map.subroutines || []), ...(map.variables || []), ...(map.arrays || [])].forEach((entry) => {
    const name = String(entry?.name || "").trim();
    const address = Number(entry?.address);
    if (name && Number.isFinite(address) && !unique.has(name)) unique.set(name, address & 0xFFFF);
  });
  return [...unique.entries()]
    .map(([name, address]) => ({ name, address }))
    .sort((left, right) => (left.address - right.address) || left.name.localeCompare(right.name));
}

function _debuggerStartOptions(hasBasicSysStub, codeOrigin, enabled = debuggerJmp) {
  if (!enabled) return { autoJmp: false, jmpAddress: undefined };
  if (hasBasicSysStub) return { autoJmp: true, jmpAddress: undefined };
  return { autoJmp: false, jmpAddress: codeOrigin };
}

async function _ubRunDebugger() {
  const target = await _ubBuildTarget();
  if (target.error) { _ubSetStatus(target.error, true); return; }
  if (!target.source.trim()) {
    _ubSetStatus(t("ubNothingToRun"), true);
    return;
  }
  if (!debuggerPath) {
    _ubSetStatus(t("debuggerNotConfiguredMsg"), true);
    return;
  }
  if (!window.electronAPI?.launchDebugger) {
    _ubSetStatus(t("debuggerLaunchNotAvailable"), true);
    return;
  }

  await showWorkProgress("workProgressDebug");
  let success = false;
  try {
    setWorkProgress(20);
    const build = await _ubCompileTarget(target, { skipExomizer: true });
    if (!build) return;
    setWorkProgress(60);
    const breakpointLines = target.startup
      ? (Array.isArray(target.breakpoints) ? target.breakpoints : [])
      : _getTabBreakpointLines("ub");
    const result = await window.electronAPI.launchDebugger({
      bytes: Array.from(build.prg || []),
      fileName: `ultimate-basic-${Date.now()}.prg`,
      symbols: _ubDebuggerSymbols(build),
      breakpoints: _ubBreakpointAddresses(build, breakpointLines),
      sidecars: build.debug || null,
      ..._debuggerStartOptions(true, build.map?.loadAddress),
      waitMs: debuggerWait ? debuggerWaitMs : 0,
      unpause: debuggerUnpause || undefined
    });
    if (!result?.ok) {
      _ubSetStatus(result?.error || t("debuggerLaunchFailed"), true);
      return;
    }
    setWorkProgress(100);
    _ubSetStatus(t("debuggerLaunched"));
    success = true;
  } catch (error) {
    const message = error?.message || String(error) || t("debuggerLaunchFailed");
    _ubSetBuildOutput(message, true);
    _ubSetStatus(message, true);
  } finally {
    if (success) await completeWorkProgress("workProgressSuccessDebug");
    else hideWorkProgress();
  }
}

// Select the block whose _srcLine best matches the given source line (used
// when switching from Expert mode to Block mode to preserve caret context).
function _selectBlockBySourceLine(sourceLine) {
  if (!Array.isArray(program) || program.length === 0) return;
  // Prefer exact match; otherwise pick the last block with _srcLine <= sourceLine.
  let exact = null;
  let bestBelow = null;
  for (const block of program) {
    const sl = typeof block._srcLine === "number" ? block._srcLine : -1;
    if (sl === sourceLine) { exact = block; break; }
    if (sl >= 0 && sl <= sourceLine) {
      if (!bestBelow || (typeof bestBelow._srcLine === "number" && sl > bestBelow._srcLine)) {
        bestBelow = block;
      }
    }
  }
  const target = exact || bestBelow || program[0];
  if (!target?.id) return;
  // Wait one frame so renderProgram() has attached DOM nodes.
  requestAnimationFrame(() => {
    selectBlockInAsm(target.id);
    const node = _blockFindNode(`[data-block-id="${target.id}"]`);
    if (node) _scrollIntoContainer(node);
  });
}

// Centres node in its nearest scrolling ancestor only. scrollIntoView() scrolls
// every scrollable ancestor, the page too, so on the Expert → Block switch the
// header (eyebrow, toolbar) slid out of view for a moment.
function _scrollIntoContainer(node) {
  let box = node.parentElement;
  while (box && box !== document.body && box !== document.documentElement) {
    const oy = getComputedStyle(box).overflowY;
    if ((oy === "auto" || oy === "scroll") && box.scrollHeight > box.clientHeight) break;
    box = box.parentElement;
  }
  if (!box || box === document.body || box === document.documentElement) return;
  const br = box.getBoundingClientRect(), nr = node.getBoundingClientRect();
  box.scrollTop += (nr.top - br.top) - (box.clientHeight - nr.height) / 2;
}

function _expertSetStatus(text, type) {
  if (!expertStatus) return;
  expertStatus.textContent = text;
  expertStatus.className = "expert-status" + (type ? " expert-status--" + type : "");
}

function renderExpertOriginInfo() {
  const el = document.getElementById("expert-origin-info");
  if (!el) return;
  const text = _expertGetSourceText();
  const useBasicSys = basicSysToggle ? basicSysToggle.checked : true;

  // Find first * = $XXXX or * = XXXX directive (not in a comment)
  let origin = null;
  for (const line of text.split("\n")) {
    const stripped = line.replace(/;.*$/, "").trim();
    const m = stripped.match(/^\*\s*=\s*\$(\s*[0-9A-Fa-f]{1,4})\b/) ||
              stripped.match(/^\*\s*=\s*(\d{1,5})\b/);
    if (m) {
      const isHex = stripped.includes("$");
      origin = isHex ? parseInt(m[1].trim(), 16) : parseInt(m[1], 10);
      break;
    }
  }
  if (origin === null) origin = defaultOrigin;

  if (!useBasicSys) {
    el.textContent = `* = $${origin.toString(16).toUpperCase().padStart(4,"0")} (${origin}) ⚠ No BASIC SYS`;
    el.className = "expert-origin-info expert-origin-info--warn";
  } else {
    // With BASIC SYS stub, show the actual SYS address
    const rawOrigin = (origin === 0x0801) ? 0x080D : origin;
    const stubDigits = String(rawOrigin).length;
    const stubDataSize = 2 + 2 + 1 + stubDigits + 1 + 2;
    const codeAddr = Math.max(rawOrigin, 0x0801 + stubDataSize);
    el.textContent = `SYS ${codeAddr} ($${codeAddr.toString(16).toUpperCase().padStart(4,"0")})`;
    el.className = "expert-origin-info";
  }
}

